"""Sparse-patch tests use only freshly generated bytes."""

import hashlib
import json
from pathlib import Path
import sys
import tempfile
import unittest
from unittest.mock import patch
import warnings
import zipfile

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
from mysticnights.patch import PatchError, apply_patch, build_patch, inspect_patch


class SparsePatchTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.original = self.root / "original.bin"
        self.modified = self.root / "modified.bin"
        self.package = self.root / "changes.zip"
        self.original.write_bytes(bytes(range(256)) * 20)
        data = bytearray(self.original.read_bytes())
        data[8:13] = b"Hello"
        data[1000:1010] = b"translated"
        data[-1] = 17
        self.modified.write_bytes(data)
        self.manifest = build_patch(self.original, self.modified, self.package)

    def test_forward_and_reverse_exact_identity(self):
        out = self.root / "applied.bin"
        restored = self.root / "restored.bin"
        result = apply_patch(self.original, self.package, out)
        self.assertEqual(result["mode"], "apply")
        self.assertEqual(out.read_bytes(), self.modified.read_bytes())
        rollback = apply_patch(out, self.package, restored, reverse=True)
        self.assertEqual(rollback["mode"], "rollback")
        self.assertEqual(restored.read_bytes(), self.original.read_bytes())
        self.assertEqual(rollback["sha256"], self.manifest["original"]["sha256"])
        self.assertEqual(out.read_bytes(), self.modified.read_bytes())

    def test_manifest_inventory(self):
        manifest = inspect_patch(self.package)
        self.assertEqual(manifest, self.manifest)
        self.assertEqual([(x["offset"], x["size"]) for x in manifest["ranges"]], [(8, 5), (1000, 10), (5119, 1)])
        self.assertLess(self.package.stat().st_size, self.original.stat().st_size)

    def test_deterministic_output(self):
        second = self.root / "second.zip"
        build_patch(self.original, self.modified, second)
        self.assertEqual(second.read_bytes(), self.package.read_bytes())

    def test_equal_files_produce_identity_patch(self):
        package = self.root / "identity.zip"
        manifest = build_patch(self.original, self.original, package)
        self.assertEqual(manifest["ranges"], [])
        out = self.root / "identity.bin"
        apply_patch(self.original, package, out)
        self.assertEqual(out.read_bytes(), self.original.read_bytes())

    def test_empty_file_roundtrip(self):
        blank = self.root / "empty.bin"
        blank.write_bytes(b"")
        package = self.root / "empty.zip"
        build_patch(blank, blank, package)
        out = self.root / "empty-applied.bin"
        apply_patch(blank, package, out)
        self.assertEqual(out.read_bytes(), b"")

    def test_merge_gap_and_chunk_boundary(self):
        self.original.write_bytes(b"a" * 100)
        data = bytearray(self.original.read_bytes())
        data[15], data[18], data[32] = 98, 99, 100
        self.modified.write_bytes(data)
        package = self.root / "boundary.zip"
        with patch("mysticnights.patch._CHUNK", 16):
            manifest = build_patch(self.original, self.modified, package, merge_gap=2)
            self.assertEqual([(x["offset"], x["size"]) for x in manifest["ranges"]], [(15, 4), (32, 1)])
            out = self.root / "boundary.bin"
            apply_patch(self.original, package, out)
            self.assertEqual(out.read_bytes(), data)

    def test_rejects_unequal_sizes(self):
        self.modified.write_bytes(b"short")
        with self.assertRaisesRegex(PatchError, "equal-sized"):
            build_patch(self.original, self.modified, self.root / "bad.zip")

    def test_rejects_bad_merge_gap(self):
        for value in (-1, 4097, True, 1.5):
            with self.subTest(value=value), self.assertRaises(ValueError):
                build_patch(self.original, self.modified, self.root / "bad.zip", merge_gap=value)

    def test_rejects_unknown_source_without_output(self):
        data = bytearray(self.original.read_bytes())
        data[0] ^= 1
        self.original.write_bytes(data)
        out = self.root / "out.bin"
        with self.assertRaisesRegex(PatchError, "SHA-256"):
            apply_patch(self.original, self.package, out)
        self.assertFalse(out.exists())

    def test_rejects_wrong_direction(self):
        with self.assertRaisesRegex(PatchError, "SHA-256"):
            apply_patch(self.modified, self.package, self.root / "out.bin")

    def test_existing_outputs_are_not_overwritten(self):
        for path in (self.original, self.modified, self.package):
            original = path.read_bytes()
            with self.subTest(path=path), self.assertRaises(FileExistsError):
                apply_patch(self.original, self.package, path)
            self.assertEqual(path.read_bytes(), original)
        with self.assertRaises(FileExistsError):
            build_patch(self.original, self.modified, self.package)

    def rewrite(self, mutator=None, members=None, manifest_bytes=None):
        with zipfile.ZipFile(self.package, "r") as archive:
            contents = {x: archive.read(x) for x in archive.namelist()}
        manifest = json.loads(contents["manifest.json"])
        if mutator:
            mutator(manifest)
        contents["manifest.json"] = manifest_bytes if manifest_bytes is not None else json.dumps(manifest).encode()
        if members:
            contents.update(members)
        target = self.root / "malformed.zip"
        with zipfile.ZipFile(target, "w") as archive:
            for name, value in contents.items():
                archive.writestr(name, value)
        return target

    def test_corrupt_payload_is_rejected_before_output(self):
        package = self.rewrite(members={"after/000000.bin": b"wrong"})
        out = self.root / "out.bin"
        with self.assertRaisesRegex(PatchError, "payload SHA-256"):
            apply_patch(self.original, package, out)
        self.assertFalse(out.exists())

    def test_expected_bytes_independently_verified(self):
        fake = b"WRONG"
        def mutate(manifest):
            manifest["ranges"][0]["before_sha256"] = hashlib.sha256(fake).hexdigest()
        package = self.rewrite(mutate, members={"before/000000.bin": fake})
        out = self.root / "out.bin"
        with self.assertRaisesRegex(PatchError, "expected bytes"):
            apply_patch(self.original, package, out)
        self.assertFalse(out.exists())

    def test_wrong_output_hash_removes_partial_output(self):
        def mutate(manifest):
            manifest["modified"]["sha256"] = "0" * 64
        package = self.rewrite(mutate)
        out = self.root / "out.bin"
        original = self.original.read_bytes()
        with self.assertRaisesRegex(PatchError, "output SHA-256"):
            apply_patch(self.original, package, out)
        self.assertFalse(out.exists())
        self.assertEqual(self.original.read_bytes(), original)

    def test_rejects_overlap_and_out_of_bounds(self):
        for offset in (8, 999999):
            with self.subTest(offset=offset):
                package = self.rewrite(lambda m: m["ranges"][1].__setitem__("offset", offset))
                with self.assertRaisesRegex(PatchError, "overlap.*outside"):
                    inspect_patch(package)

    def test_rejects_boolean_integer_field(self):
        package = self.rewrite(lambda m: m["ranges"][0].__setitem__("offset", True))
        with self.assertRaisesRegex(PatchError, "integer"):
            inspect_patch(package)

    def test_rejects_traversal_and_extra_members(self):
        package = self.rewrite(lambda m: m["ranges"][0].__setitem__("before", "../file"))
        with self.assertRaisesRegex(PatchError, "member path"):
            inspect_patch(package)
        package = self.rewrite(members={"../file": b"x"})
        with self.assertRaisesRegex(PatchError, "additional"):
            inspect_patch(package)

    def test_rejects_duplicate_json_keys(self):
        package = self.rewrite(manifest_bytes=b'{"format":"x","format":"y"}')
        with self.assertRaisesRegex(PatchError, "Duplicate JSON"):
            inspect_patch(package)

    def test_rejects_invalid_utf8_manifest(self):
        package = self.rewrite(manifest_bytes=json.dumps(self.manifest).encode("utf-16"))
        with self.assertRaisesRegex(PatchError, "UTF-8"):
            inspect_patch(package)

    def test_rejects_duplicate_zip_member(self):
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", UserWarning)
            with zipfile.ZipFile(self.package, "a") as archive:
                archive.writestr("manifest.json", b"{}")
        with self.assertRaisesRegex(PatchError, "duplicate ZIP"):
            inspect_patch(self.package)

    def test_rejects_unsupported_version(self):
        package = self.rewrite(lambda m: m.__setitem__("version", 999))
        with self.assertRaisesRegex(PatchError, "version"):
            inspect_patch(package)

    def test_rejects_inconsistent_member_length(self):
        package = self.rewrite(members={"before/000000.bin": b"x"})
        with self.assertRaisesRegex(PatchError, "metadata"):
            inspect_patch(package)


if __name__ == "__main__":
    unittest.main()
